part of 'conversion.dart';

/// Small, internal-only OPC writer. All names are generated by this library;
/// document names, URLs and embedded stream names never become ZIP paths.
class _OpcPackageWriter {
  final _parts = <String, _OpcPart>{};
  final _relationships = <String, List<_OpcRelationship>>{};
  var _totalBytes = 0;
  var _xmlBytes = 0;

  void addXml(String path, String contentType, _BoundedWordXml xml) {
    _xmlBytes += xml.byteEstimate;
    if (_xmlBytes > kLegacyWordDocxXmlLimit) _tooComplex();
    addBytes(
      path,
      contentType,
      Uint8List.fromList(utf8.encode(xml.toString())),
    );
  }

  void addBytes(String path, String contentType, Uint8List bytes) {
    _validatePartName(path);
    if (_parts.containsKey(path) || _parts.length >= 4096) _tooComplex();
    _totalBytes += bytes.length;
    if (_totalBytes > kLegacyWordPackageLimit) _tooComplex();
    _parts[path] = _OpcPart(contentType, Uint8List.fromList(bytes));
  }

  String relate(String from, String type, String target) {
    if (from.isNotEmpty) _validatePartName(from);
    _validatePartName(target);
    final values = _relationships.putIfAbsent(from, () => []);
    for (final existing in values) {
      if (existing.type == type && existing.target == target) {
        return existing.id;
      }
    }
    if (values.length >= 4096) _tooComplex();
    final id = 'rId${values.length + 1}';
    values.add(_OpcRelationship(id, type, target));
    return id;
  }

  Uint8List encode() {
    final archive = Archive();
    void file(String name, Uint8List bytes) {
      final value = ArchiveFile.bytes(name, bytes)..lastModTime = 315532800;
      archive.addFile(value);
    }

    final contentTypes = _BoundedWordXml()
      ..add(
        '<?xml version="1.0" encoding="UTF-8"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
      );
    for (final entry in _parts.entries) {
      contentTypes.add('<Override PartName="/${entry.key}" ContentType="');
      contentTypes.text(entry.value.contentType, attribute: true);
      contentTypes.add('"/>');
    }
    contentTypes.add('</Types>');
    file(
      '[Content_Types].xml',
      Uint8List.fromList(utf8.encode(contentTypes.toString())),
    );
    for (final entry in _parts.entries) file(entry.key, entry.value.bytes);
    for (final entry in _relationships.entries) {
      final source = entry.key;
      if (source.isNotEmpty && !_parts.containsKey(source)) {
        throw const FormatException(
          'A package relationship has no source part.',
        );
      }
      final slash = source.lastIndexOf('/');
      final directory = slash < 0 ? '' : source.substring(0, slash + 1);
      final filename = slash < 0 ? source : source.substring(slash + 1);
      final path = source.isEmpty
          ? '_rels/.rels'
          : '${directory}_rels/$filename.rels';
      final xml = _BoundedWordXml()
        ..add(
          '<?xml version="1.0" encoding="UTF-8"?>'
          '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">',
        );
      for (final relationship in entry.value) {
        if (!_parts.containsKey('$directory${relationship.target}')) {
          throw const FormatException(
            'A package relationship has no target part.',
          );
        }
        xml.add('<Relationship Id="${relationship.id}" Type="');
        xml.text(relationship.type, attribute: true);
        xml.add('" Target="${relationship.target}"/>');
      }
      xml.add('</Relationships>');
      final bytes = Uint8List.fromList(utf8.encode(xml.toString()));
      _totalBytes += bytes.length;
      if (_totalBytes > kLegacyWordPackageLimit) _tooComplex();
      file(path, bytes);
    }
    final encoded = Uint8List.fromList(ZipEncoder().encode(archive));
    if (encoded.length > kLegacyWordPackageLimit) _tooComplex();
    return encoded.asUnmodifiableView();
  }

  static void _validatePartName(String path) {
    if (!RegExp(r'^[A-Za-z0-9_-][A-Za-z0-9_./-]*$').hasMatch(path) ||
        path
            .split('/')
            .any((part) => part.isEmpty || part == '.' || part == '..')) {
      throw const FormatException('Invalid generated package part name.');
    }
  }
}

class _OpcPart {
  const _OpcPart(this.contentType, this.bytes);
  final String contentType;
  final Uint8List bytes;
}

class _OpcRelationship {
  const _OpcRelationship(this.id, this.type, this.target);
  final String id;
  final String type;
  final String target;
}
